    /// Start of range for backfill (ISO 8601: YYYY-MM-DD). Alias for --event-time-start.
    #[arg(long)]
    start: Option<String>,

    /// End of range for backfill (exclusive, ISO 8601: YYYY-MM-DD). Alias for --event-time-end.
    #[arg(long)]
